<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])){header('Location: login.php');exit;} $id=(int)($_POST['id']??0);$tienda=(int)($_POST['tienda_id']??0);$nombre=trim((string)($_POST['nombre']??''));$desc=trim((string)($_POST['descripcion']??''));$precio=(float)($_POST['precio']??-1);$oferta=trim((string)($_POST['precio_oferta']??''));$estado=(string)($_POST['estado']??'');if(!$id||!$tienda||$nombre===''||$precio<0||!in_array($estado,['activo','inactivo','agotado'],true)){http_response_code(400);exit('Datos no válidos.');}$config=require __DIR__.'/config.php';try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$q=$pdo->prepare('UPDATE productos SET tienda_id=?,nombre=?,descripcion=?,precio=?,precio_oferta=?,estado=? WHERE id=?');$q->execute([$tienda,$nombre,$desc,number_format($precio,2,'.',''),$oferta===''?null:number_format((float)$oferta,2,'.',''),$estado,$id]);header('Location: panel.php?product_updated=1');}catch(Throwable $e){http_response_code(500);exit('No se pudo actualizar el producto.');}
